<?php
namespace App\Controllers;
use App\Core\Database;
final class DownloadController{public function file():never{$token=(string)($_GET['token']??'');$id=(int)($_GET['id']??0);if(strlen($token)!==48||$id<1){http_response_code(403);exit('Descarga no autorizada');}$s=Database::db()->prepare("SELECT p.original_path,p.download_enabled FROM orders o JOIN order_items i ON i.order_id=o.id JOIN photos p ON p.id=i.photo_id WHERE o.download_token=? AND p.id=? AND o.status='paid' AND o.paid_at IS NOT NULL");$s->execute([$token,$id]);$p=$s->fetch();$root=realpath(ROOT.'/storage/originals');$file=$p?realpath(ROOT.'/'.ltrim($p['original_path'],'/')):false;if(!$p||!$p['download_enabled']||!$root||!$file||!str_starts_with($file,$root.DIRECTORY_SEPARATOR)||!is_file($file)){http_response_code(403);exit('Descarga no autorizada');}header('Content-Type: application/octet-stream');header('Content-Disposition: attachment; filename="ultra-fotografia-'.$id.'.'.pathinfo($file,PATHINFO_EXTENSION).'"');header('Content-Length: '.filesize($file));header('Cache-Control: private, no-store, no-cache, must-revalidate');header('Pragma: no-cache');header('X-Content-Type-Options: nosniff');readfile($file);exit;}}
